2	 * Handle timeouts greater than 32-bit signed integer
3	 */
4	class LongTimeout {
5	  constructor() {
6	    this.timeout = 0
7	    this.timer = null
8	  }
9	
10	  clear() {
11	    clearTimeout(this.timer)
12	  }
