14	  /**
15	   *
16	   * @param {Function} fn
17	   * @param {number} timeout
18	   */
19	  set(fn, timeout) {
20	    const maxValue = 2147483647
21	
22	    const handleTimeout = () => {
23	      if (this.timeout > 0) {
24	        let delay = Math.min(this.timeout, maxValue)
25	        this.timeout = this.timeout - delay
26	        this.timer = setTimeout(handleTimeout, delay)
27	        return
28	      }
29	      fn()
30	    }
31	
32	    this.timeout = timeout
33	    handleTimeout()
