// Compares the compiled output of converted modules against the pristine baseline build at the syntax-tree level.
// Two files are AST-identical when they are the same program: they may differ only in comments, whitespace,
// quote style and redundant parentheses, none of which can change behaviour.
//
// Usage: node astdiff.js <repo root> <baseline dist dir> <relative path without extension> [...]
const fs = require('fs')
const path = require('path')

const [repoRoot, baselineDir, ...rels] = process.argv.slice(2)
const acorn = require(path.join(repoRoot, 'node_modules', 'acorn'))

function parse(file) {
  const src = fs.readFileSync(file, 'utf8')
  const comments = []
  const ast = acorn.parse(src, { ecmaVersion: 'latest', sourceType: 'script', allowHashBang: true, onComment: comments })
  return { ast, src, comments }
}

// Drop position info. Literal.raw is dropped too (quote style / numeric spelling), but the cooked `value`,
// `regex` and `bigint` fields are kept, and TemplateElement.value.raw is kept.
function clean(node, parentType) {
  if (Array.isArray(node)) return node.map((n) => clean(n, parentType))
  if (node && typeof node === 'object') {
    if (node instanceof RegExp) return { __regexp: String(node) }
    const out = {}
    for (const key of Object.keys(node)) {
      if (key === 'start' || key === 'end' || key === 'loc' || key === 'range') continue
      if (key === 'raw' && node.type === 'Literal') continue
      const v = node[key]
      out[key] = typeof v === 'bigint' ? { __bigint: String(v) } : clean(v, node.type)
    }
    return out
  }
  return node
}

function firstDifference(a, b, trail) {
  if (a === b) return null
  if (typeof a !== typeof b || a === null || b === null || typeof a !== 'object') return `${trail}: ${JSON.stringify(a)} !== ${JSON.stringify(b)}`
  if (Array.isArray(a) !== Array.isArray(b)) return `${trail}: array/object mismatch`
  const keys = new Set([...Object.keys(a), ...Object.keys(b)])
  for (const key of keys) {
    if (!(key in a) || !(key in b)) return `${trail}.${key}: present on one side only`
    const d = firstDifference(a[key], b[key], `${trail}.${key}`)
    if (d) return d
  }
  return null
}

let failed = false
for (const rel of rels) {
  const baseFile = path.join(baselineDir, rel + '.js')
  const newFile = path.join(repoRoot, 'dist-server', rel + '.js')
  const base = parse(baseFile)
  const now = parse(newFile)
  const diff = firstDifference(clean(base.ast), clean(now.ast), 'Program')
  const bytes = base.src === now.src
  const commentsSame = JSON.stringify(base.comments.map((c) => c.value)) === JSON.stringify(now.comments.map((c) => c.value))
  let verdict
  if (bytes) verdict = 'BYTE-IDENTICAL'
  else if (!diff) verdict = `AST-IDENTICAL (text differs${commentsSame ? '' : '; comments differ'})`
  else {
    verdict = `DIFFERENT -> ${diff}`
    failed = true
  }
  console.log(`${rel}.js: ${verdict}`)
}
process.exit(failed ? 1 : 0)

