function parseNfoMetadata(nfoText) {
  if (!nfoText) return null
  const lines = nfoText.split(/\r?\n/)
  const metadata = {}
  let insideBookDescription = false
  lines.forEach(line => {
    if (line.search(/^\s*book description\s*$/i) !== -1) {
