// JavaScript instantiates every top-level function declaration before the first statement of the file runs, so where a
// function declaration sits relative to the other statements cannot affect execution. Model that by moving them to the
// front, keeping the relative order of the declarations and of the remaining statements (tsc emits `export =` last).
function hoistFunctionDeclarations(program) {
  const fns = program.body.filter((n) => n.type === 'FunctionDeclaration')
  const rest = program.body.filter((n) => n.type !== 'FunctionDeclaration')
  return { ...program, body: [...fns, ...rest] }
}

let failed = false
for (const rel of rels) {
  const baseFile = path.join(baselineDir, rel + '.js')
  const newFile = path.join(repoRoot, 'dist-server', rel + '.js')
  const base = parse(baseFile)
  const now = parse(newFile)
  const baseAst = clean(base.ast)
  const nowAst = clean(now.ast)
  const diff = firstDifference(baseAst, nowAst, 'Program')
  const bytes = base.src === now.src
  const commentsSame = JSON.stringify(base.comments.map((c) => c.value)) === JSON.stringify(now.comments.map((c) => c.value))
  let verdict
  if (bytes) verdict = 'BYTE-IDENTICAL'
  else if (!diff) verdict = `AST-IDENTICAL (text differs${commentsSame ? '' : '; comments differ'})`
  else {
    const hoistedDiff = firstDifference(hoistFunctionDeclarations(baseAst), hoistFunctionDeclarations(nowAst), 'Program')
    if (!hoistedDiff) verdict = `AST-IDENTICAL AFTER HOISTING (only the position of a statement relative to hoisted top-level function declarations differs${commentsSame ? '' : '; comments differ'})`
    else {
      verdict = `DIFFERENT -> ${diff}`
      failed = true
    }
  }
  console.log(`${rel}.js: ${verdict}`)
}

