// Compares the compiled output of converted modules against the pristine baseline build at the syntax-tree level.
// Two files are AST-identical when they are the same program: they may differ only in comments, whitespace,
// quote style and redundant parentheses, none of which can change behaviour.
//
// Usage: node astdiff.js <repo root> <baseline dist dir> <relative path without extension> [...]
const fs = require('fs')
const path = require('path')

const [repoRoot, baselineDir, ...rels] = process.argv.slice(2)
const acorn = require(path.join(repoRoot, 'node_modules', 'acorn'))

function parse(file) {
  const src = fs.readFileSync(file, 'utf8')
  const comments = []
  const ast = acorn.parse(src, { ecmaVersion: 'latest', sourceType: 'script', allowHashBang: true, onComment: comments })
  return { ast, src, comments }
}

// Drop position info. Literal.raw is dropped too (quote style / numeric spelling), but the cooked `value`,
// `regex` and `bigint` fields are kept, and TemplateElement.value.raw is kept.
function clean(node, parentType) {
  if (Array.isArray(node)) return node.map((n) => clean(n, parentType))
  if (node && typeof node === 'object') {
    if (node instanceof RegExp) return { __regexp: String(node) }
    const out = {}
    for (const key of Object.keys(node)) {
      if (key === 'start' || key === 'end' || key === 'loc' || key === 'range') continue
      if (key === 'raw' && node.type === 'Literal') continue
      const v = node[key]
      out[key] = typeof v === 'bigint' ? { __bigint: String(v) } : clean(v, node.type)
    }
    return out
  }
  return node
}

function firstDifference(a, b, trail) {
  if (a === b) return null
  if (typeof a !== typeof b || a === null || b === null || typeof a !== 'object') return `${trail}: ${JSON.stringify(a)} !== ${JSON.stringify(b)}`
  if (Array.isArray(a) !== Array.isArray(b)) return `${trail}: array/object mismatch`
  const keys = new Set([...Object.keys(a), ...Object.keys(b)])
  for (const key of keys) {
    if (!(key in a) || !(key in b)) return `${trail}.${key}: present on one side only`
    const d = firstDifference(a[key], b[key], `${trail}.${key}`)
    if (d) return d
  }
  return null
}

// JavaScript instantiates every top-level function declaration before the first statement of the file runs, so where a
// function declaration sits relative to the other statements cannot affect execution. Model that by moving them to the
// front, keeping the relative order of the declarations and of the remaining statements (tsc emits `export =` last).
function hoistFunctionDeclarations(program) {
  const fns = program.body.filter((n) => n.type === 'FunctionDeclaration')
  const rest = program.body.filter((n) => n.type !== 'FunctionDeclaration')
  return { ...program, body: [...fns, ...rest] }
}

function countIdentifier(node, name) {
  if (Array.isArray(node)) return node.reduce((n, child) => n + countIdentifier(child, name), 0)
  if (node && typeof node === 'object') {
    let n = node.type === 'Identifier' && node.name === name ? 1 : 0
    for (const key of Object.keys(node)) n += countIdentifier(node[key], name)
    return n
  }
  return 0
}

// `import X = require('m')` followed by `const Y = X.member` compiles to two statements where the JavaScript source had
// `const Y = require('m').member`. When X is a top-level const, the very next statement is its only use, and that use is a
// plain member read, folding the two back together cannot change evaluation order or anything observable.
// Any other occurrence of the name X anywhere in the file (even as a property name) disables the rewrite.
function inlineSingleUseRequire(program) {
  const body = []
  for (let i = 0; i < program.body.length; i++) {
    const a = program.body[i]
    const b = program.body[i + 1]
    const isRequireConst = a.type === 'VariableDeclaration' && a.kind === 'const' && a.declarations.length === 1 && a.declarations[0].id.type === 'Identifier' && a.declarations[0].init?.type === 'CallExpression' && a.declarations[0].init.callee.type === 'Identifier' && a.declarations[0].init.callee.name === 'require'
    if (isRequireConst && b && b.type === 'VariableDeclaration' && b.kind === 'const' && b.declarations.length === 1) {
      const name = a.declarations[0].id.name
      const init = b.declarations[0].init
      if (init?.type === 'MemberExpression' && !init.computed && !init.optional && init.object.type === 'Identifier' && init.object.name === name && countIdentifier(program, name) === 2) {
        body.push({ ...b, declarations: [{ ...b.declarations[0], init: { ...init, object: a.declarations[0].init } }] })
        i++
        continue
      }
    }
    body.push(a)
  }
  return { ...program, body }
}

let failed = false
for (const rel of rels) {
  const baseFile = path.join(baselineDir, rel + '.js')
  const newFile = path.join(repoRoot, 'dist-server', rel + '.js')
  const base = parse(baseFile)
  const now = parse(newFile)
  const baseAst = clean(base.ast)
  const nowAst = clean(now.ast)
  const diff = firstDifference(baseAst, nowAst, 'Program')
  const bytes = base.src === now.src
  const commentsSame = JSON.stringify(base.comments.map((c) => c.value)) === JSON.stringify(now.comments.map((c) => c.value))
  let verdict
  if (bytes) verdict = 'BYTE-IDENTICAL'
  else if (!diff) verdict = `AST-IDENTICAL (text differs${commentsSame ? '' : '; comments differ'})`
  else {
    const hoistedDiff = firstDifference(hoistFunctionDeclarations(baseAst), hoistFunctionDeclarations(nowAst), 'Program')
    if (!hoistedDiff) verdict = `AST-IDENTICAL AFTER HOISTING (only the position of a statement relative to hoisted top-level function declarations differs${commentsSame ? '' : '; comments differ'})`
    else {
      verdict = `DIFFERENT -> ${diff}`
      failed = true
    }
  }
  console.log(`${rel}.js: ${verdict}`)
}
process.exit(failed ? 1 : 0)

