    'construct from partial JSON': (T) => tagsSnapshot(new T({ tagTitle: 'T', tagASIN: 'A', tagTrack: '7', tagUnknown: 'ignored', tagGenre: '', tagDisc: null })),
    'setData from probe tags': (T) => { const t = new T(); const r = t.setData(probeTags); return { r, ...tagsSnapshot(t) } },
    'setData({}) clears': (T) => { const t = new T({ tagTitle: 'T' }); t.setData({}); return tagsSnapshot(t) },
    'setData(undefined) throws': (T) => { const t = new T(); return t.setData(undefined) },
    'updateData reports change then no change': (T) => { const t = new T(); return { first: t.updateData(probeTags), second: t.updateData(probeTags), third: t.updateData({ ...probeTags, file_tag_album: 'Other' }), fourth: t.updateData({}), ...tagsSnapshot(t) } },
    'clone is independent and equal': (T) => { const t = new T(); t.setData(probeTags); const c = t.clone(); const sameClass = c instanceof T; c.tagAlbum = 'Changed'; return { sameClass, original: t.tagAlbum, clone: tagsSnapshot(c), eqBefore: t.isEqual(t.clone()), eqAfter: t.isEqual(c) } },
    'isEqual edge cases': (T) => { const a = new T({ tagTitle: 'T', tagAlbum: 'A' }); const fewer = new T({ tagTitle: 'T' }); const more = new T({ tagTitle: 'T', tagAlbum: 'A', tagArtist: 'X' }); return [a.isEqual(null), a.isEqual(undefined), a.isEqual({}), a.isEqual({ tagTitle: 'T' }), a.isEqual(a), a.isEqual(fewer), fewer.isEqual(a), a.isEqual(more), a.isEqual({ toJSON: () => ({ tagTitle: 'T', other: undefined }), tagTitle: 'T' })] },
    'toJSON picks up ad-hoc tag* properties and ignores others': (T) => { const t = new T({ tagTitle: 'T' }); t.tagCustom = 'C'; t.other = 'O'; t.tagZero = 0; return { json: t.toJSON(), keys: Object.keys(t) } },
    'number parsing': (T) => ['3/10', '3', '03/010', '3.9/10.5', 'x/y', '/', '', ' 4 / 5 ', '1/2/3', '-1/-2', '1e2/0x10', 'Infinity/NaN', '0/0', 5, null].map((v) => { const t = new T(); t.tagTrack = v; t.tagDisc = v; try { return [v, t.trackNumAndTotal, t.discNumAndTotal, t.trackNumber, t.trackTotal, t.discNumber, t.discTotal] } catch (e) { return [v, 'threw', e.message] } })
  }
  for (const [label, run] of Object.entries(tagScripts)) await both('AudioMetaTags', label, 'server/objects/metadata/AudioMetaTags', run)

  // ---------------------------------------------------------------- OpenLibrary (axios.get replaced; no network)
  const axios = require(path.join(repo, 'node_modules', 'axios'))
  const realGet = axios.get
