      { key: '/works/OL2W', title: 'Good Book 2' },
      { key: '/works/OL3W', title: 'No Works', first_publish_year: 'abc' },
      { key: '/works/OL4W', title: 'Year From Works', author_name: [] },
      { key: '/works/OL5W', title: 'Bad Works Year', cover_edition_key: '' }
    ] } },
    'https://openlibrary.org//search.json?title=Empty': { data: { docs: [] } },
    'https://openlibrary.org//search.json?q=x&limit=2&flag=true': { data: { docs: [{ key: '/works/OL1W', title: 'Via search()' }] } },
    'https://openlibrary.org//works/OL1W.json': { data: { covers: [12, -1, 0, 34], description: 'Plain description', first_publish_date: '2001-05-06' } },
    'https://openlibrary.org//works/OL2W.json': { data: { description: { type: '/type/text', value: 'Object description' } } },
    'https://openlibrary.org//works/OL4W.json': { data: { covers: [], description: { value: '' }, first_publish_date: '1984' } },
    'https://openlibrary.org//works/OL5W.json': { data: { description: '', first_publish_date: 'circa 1900' } },
    'https://openlibrary.org/plain': { data: 'text body' },
    'https://openlibrary.org/zero': { data: 0 }
  }
  const openLibraryScripts = {
    'baseUrl and own keys': (ol) => ({ keys: Object.keys(ol), baseUrl: ol.baseUrl }),
    'get: default, explicit and invalid timeouts': async (ol) => [await ol.get('plain'), await ol.get('plain', 5000), await ol.get('plain', 0), await ol.get('plain', NaN), await ol.get('plain', null), await ol.get('plain', 'abc'), await ol.get('plain', '250'), await ol.get('zero'), await ol.get('missing')],
    'isbnLookup found': (ol) => ol.isbnLookup('9780000000000'),
    'isbnLookup not found': (ol) => ol.isbnLookup('0'),
    'getWorksData variants': async (ol) => [await ol.getWorksData('/works/OL1W'), await ol.getWorksData('/works/OL2W'), await ol.getWorksData('/works/OL3W'), await ol.getWorksData('/works/OL4W'), await ol.getWorksData('/works/OL5W')],
    'parsePublishYear': (ol) => [ol.parsePublishYear({ first_publish_year: 1999 }, {}), ol.parsePublishYear({ first_publish_year: '2000' }, {}), ol.parsePublishYear({ first_publish_year: 'x' }, { first_publish_date: '1987-01-01' }), ol.parsePublishYear({}, { first_publish_date: 'March 1987' }), ol.parsePublishYear({}, { first_publish_date: '' }), ol.parsePublishYear({ first_publish_year: 0 }, { errorCode: 500, errorMsg: 'x' }), ol.parsePublishYear({}, { first_publish_date: ' 1987 -x' })],
    'cleanSearchDoc': (ol) => ol.cleanSearchDoc({ key: '/works/OL1W', title: 'Doc', author_name: ['Solo'], cover_edition_key: 'OL9M' }),
    'searchTitle with results': (ol) => ol.searchTitle('Good Book', 1234),
    'searchTitle default timeout': (ol) => ol.searchTitle('Good Book'),
    'searchTitle empty': (ol) => ol.searchTitle('Empty'),
    'searchTitle request fails': (ol) => ol.searchTitle('Nope'),
    'search': (ol) => ol.search({ q: 'x', limit: 2, flag: true }),
