// Differential test: runs each converted module from two compiled trees (the pristine baseline build and a
// candidate build) on the same inputs and compares what they return, throw, and do to their collaborators.
//
// Usage: NODE_PATH=<repo>/node_modules node difftest.js <repo root> <baseline dist> <candidate dist> <temp dir>
const path = require('path')
const util = require('util')
const fs = require('fs')

const [repo, baseDist, candDist, tmpDir] = process.argv.slice(2)
const trees = { base: baseDist, cand: candDist }
const load = (tree, rel) => require(path.join(trees[tree], rel))

const show = (v) => util.inspect(v, { depth: null, breakLength: Infinity, maxArrayLength: null, maxStringLength: null })
const stats = {}
const failures = []
const throwMessages = new Set()

// Runs fn against both trees. Outcomes are compared as text produced by util.inspect, which is sensitive to
// values, types, undefined vs missing, and property ORDER.
async function both(moduleName, label, rel, fn) {
  const out = {}
  for (const tree of ['base', 'cand']) {
    try {
      out[tree] = { value: await fn(load(tree, rel), tree) }
    } catch (e) {
      const msg = e instanceof Error ? `${e.name}: ${e.message}` : `non-Error thrown: ${show(e)}`
      throwMessages.add(`${moduleName}: ${msg}`)
      out[tree] = { threw: msg }
    }
  }
  const s = (stats[moduleName] ||= { cases: 0, failed: 0 })
  s.cases++
  if (show(out.base) !== show(out.cand)) {
    s.failed++
    failures.push(`${moduleName} / ${label}\n    baseline : ${show(out.base).slice(0, 400)}\n    candidate: ${show(out.cand).slice(0, 400)}`)
  }
}

const own = (o) => Object.fromEntries(Object.entries(o)) // plain snapshot of own enumerable props, order preserved
const UUID_V4 = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/
const maskId = (o) => ({ ...o, id: UUID_V4.test(o.id) ? '<uuid v4>' : o.id })

async function main() {
  const realNow = Date.now
  let clock = 1700000000000
  Date.now = () => (clock += 1000)
  const resetClock = () => (clock = 1700000000000)

  // ---------------------------------------------------------------- globals
  await both('globals', 'exported tables', 'server/utils/globals', (g) => g)

  // ---------------------------------------------------------------- longTimeout
  for (const ms of [0, 1, 50, 2147483647, 2147483648, 5000000000, 2147483647 * 3 + 5]) {
    await both('longTimeout', `set(${ms})`, 'server/utils/longTimeout', (LongTimeout) => {
      const log = []
      const realSet = global.setTimeout
      const realClear = global.clearTimeout
      const pending = []
      global.setTimeout = (cb, delay) => {
        log.push(['setTimeout', delay])
        pending.push(cb)
        return { fake: pending.length }
      }
      global.clearTimeout = (t) => log.push(['clearTimeout', t])
      try {
        const lt = new LongTimeout()
        log.push(['initial', own(lt)])
        lt.clear() // before set(): timer is still null
        lt.set(() => log.push(['fired']), ms)
        let guard = 0
        while (pending.length && guard++ < 20) pending.shift()()
        lt.clear()
        log.push(['final', own(lt)])
      } finally {
        global.setTimeout = realSet
        global.clearTimeout = realClear
      }
      return log
    })
  }

  // ---------------------------------------------------------------- stringifySequelizeQuery
  class DummyModel {}
  const sym = Symbol('gt')
  const queries = [
    { where: { name: 'John', age: { [sym]: 20 } } },
    { order: [[{ val: 'libraryItem.title' }, 'ASC']] },
    { include: [{ model: DummyModel, where: { [Symbol('or')]: [{ a: 1 }, { b: null }] } }] },
    { logging: (q) => q },
    { limit: 10, offset: 0, distinct: true, subQuery: false, attributes: ['id', ['a', 'b']] },
    { where: { d: new Date(0), n: null, u: undefined, nested: { deep: { deeper: [1, 2, { [sym]: 'x' }] } } } },
    {},
    DummyModel,
    [1, 2, 3],
    null
  ]
  for (const [i, q] of queries.entries()) await both('stringifySequelizeQuery', `query #${i}`, 'server/utils/stringifySequelizeQuery', (f) => f(q))

  // ---------------------------------------------------------------- hlsPlaylistGenerator (really writes the playlist)
  let fileNo = 0
  for (const type of ['mpegts', 'fmp4', 'other']) {
    for (const [duration, segLen] of [[0, 6], [5.5, 6], [6, 6], [36, 6], [3600.25, 6], [100, 10], [7, 2]]) {
      await both('hlsPlaylistGenerator', `${type} duration=${duration} segmentLength=${segLen}`, 'server/utils/generators/hlsPlaylistGenerator', async (generate) => {
        const file = path.join(tmpDir, `playlist-${fileNo++}.m3u8`)
        const result = await generate(file, 'output', duration, segLen, type)
        return { result, content: fs.readFileSync(file, 'utf8') }
      })
    }
  }

  // ---------------------------------------------------------------- areEquivalent
  const shared = [1, 2]
  const circ = { a: 1 }
  circ.self = circ
  const fnA = function abc() { return 1 }
  const fnB = function abc() { return 1 }
  const values = [0, -0, 1, '1', '', 'a', NaN, null, undefined, true, false, 10n, Symbol.for('s'), new Date(0), new Date(0), new Date(5), new Date(NaN), [], [1, 2], [1, '2'], [[1], [2]], {}, { a: 1 }, { a: '1' }, { a: 1, b: { c: [1, { d: null }] } }, { b: { c: [1, { d: null }] }, a: 1 }, { a: undefined }, fnA, fnB, () => 1, { x: shared, y: shared }, { x: [1, 2], y: [1, 2] }, circ, [{ start: 0, end: 10.5, title: 'Ch 1' }], [{ start: 0, end: '10.5', title: 'Ch 1' }]]
  for (const numToString of [false, true, undefined]) {
    for (let i = 0; i < values.length; i++) {
      for (let j = 0; j < values.length; j++) {
        await both('areEquivalent', `values[${i}] vs values[${j}] numToString=${numToString}`, 'server/utils/areEquivalent', (eq) => (numToString === undefined ? eq(values[i], values[j]) : eq(values[i], values[j], numToString)))
      }
    }
  }
  // a caller-supplied stack must be mutated the same way
  await both('areEquivalent', 'stack left behind after comparisons', 'server/utils/areEquivalent', (eq) => {
    const stack = []
    const results = [eq({ a: [1] }, { a: [1] }, false, stack), eq({ a: { b: 1 } }, { a: { b: 2 } }, false, stack), eq([1, [2]], [1, [2]], true, stack)]
    return { results, stackLength: stack.length }
  })

  // ---------------------------------------------------------------- parseNfoMetadata
  const nfos = [
    '',
    'Title: The Great Gatsby',
    'Title: The Great Gatsby: A Novel\r\nAuthor: F. Scott Fitzgerald, Someone Else ,\r\nRead By: A, B\nNarrator: C\nSeries Name: S\nPosition in Series: 2\nGenre: Fiction, Classic\nTags: t1,  t2\nPublisher: P\nASIN: B00TEST123\nISBN-13: 9780000000000\nLang: en\nUnabridged: Yes\nRelease Date: 12 Jan 1925 and 2004\nCopyright: none\n\nBook Description\n================\nLine one\n\n  Line two  \n',
    'Abridged: no\nUnabridged: no\nDate: 99\nauthor:\nTITLE:   Spaced   :  Out  \nUnknown Key: value\nno colon here',
    'Book Description\nonly description',
    'isbn: 1\nisbn-10: 2\nlanguage: de\nabridged: YES\naudible.com release: 2019-05-01',
    ':\n::\n title : x : y : z '
  ]
  for (const [i, nfo] of nfos.entries()) await both('parseNfoMetadata', `nfo #${i}`, 'server/utils/parsers/parseNfoMetadata', (m) => ({ keys: Object.keys(m), result: m.parseNfoMetadata(nfo) }))

  // ---------------------------------------------------------------- parseUserAgent
  const uas = [
    null,
    undefined,
    '',
    'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
    'Mozilla/5.0 (iPhone; CPU iPhone OS 17_1 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.1 Mobile/15E148 Safari/604.1',
    'Mozilla/5.0 (Linux; Android 13; Pixel 7 Pro) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/119.0.0.0 Mobile Safari/537.36',
    'Mozilla/5.0 (X11; Linux x86_64; rv:120.0) Gecko/20100101 Firefox/120.0',
    'Mozilla/5.0 (iPad; CPU OS 16_6 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/16.6 Mobile/15E148 Safari/604.1',
    'Mozilla/5.0 (SMART-TV; Linux; Tizen 6.0) AppleWebKit/537.36 (KHTML, like Gecko) 85.0.4183.93/6.0 TV Safari/537.36',
    'audiobookshelf/0.9.70 (Android 14; SM-S918B)',
    'okhttp/4.9.2',
    'curl/8.4.0',
    'x',
    'A'.repeat(600)
  ]
  for (const [i, ua] of uas.entries()) await both('parseUserAgent', `ua #${i}`, 'server/utils/parsers/parseUserAgent', (f) => f(ua))

  // ---------------------------------------------------------------- parseFullName
  const names = ['', 'John', 'John Smith', 'Smith, John', 'JOHN SMITH', 'john smith', 'Dr. John A. Smith Jr.', 'Mr. John "Johnny" Smith', "John 'Johnny' Smith", 'John ‘Johnny’ Smith', 'John “Johnny” Smith', 'John (Johnny) [Jo] Smith', 'Ludwig von Mises', 'von Mises', 'Vincent van Gogh', 'Juan de la Cruz y Garcia', 'Björn Bäck', 'Ursula K. Le Guin', 'J. R. R. Tolkien', 'Smith, John, Jr., PhD', 'Prof. Dr. Jane Mary Anne Doe III', 'Miss Jane Doe, MD', 'McDONALD, RONALD', 'RONALD McDONALD', 'Friedman, Milton & Friedman, Rose', 'John Smith and Jane Doe', 'A B C D E F G', 'Sir Arthur Conan Doyle', 'Mary-Jane O’Neil', 'Dr Mr Sir John Smith', 'John Smith Jr Sr', ',', ', ,', 'Jr.', 'Dr.', '  spaced   out   name  ', '李小龙', 'DE LA CRUZ, JUAN', 'e. e. cummings', 'Captain James T Kirk esq']
  const argSets = [[], ['all'], ['first'], ['LAST'], ['middle'], ['title'], ['nick'], ['suffix'], ['error'], ['bogus'], [undefined, true], [undefined, false], [undefined, 1], [undefined, 0], [undefined, -1], [undefined, 'undefined'], [undefined, undefined, true], [undefined, undefined, 1], ['all', 1, 1], [undefined, undefined, undefined, true], [undefined, undefined, undefined, 1], ['last', true, false, true]]
  for (const name of names) {
    for (const args of argSets) {
      await both('parseFullName', `${JSON.stringify(name)} args=${show(args)}`, 'server/utils/parsers/parseFullName', (parse) => parse(name, ...args))
    }
  }
  for (const bad of [null, undefined, 42, {}, ['John Smith']]) {
    await both('parseFullName', `non-string input ${show(bad)}`, 'server/utils/parsers/parseFullName', (parse) => [parse(bad), parse(bad, 'error'), parse(bad, 'first', 1)])
    await both('parseFullName', `non-string input ${show(bad)} with stopOnError`, 'server/utils/parsers/parseFullName', (parse) => parse(bad, 'all', -1, true))
  }

  // ---------------------------------------------------------------- TrackProgressMonitor
  const scripts = [
    { durations: [10, 40, 50], steps: [] },
    { durations: [10, 40, 50], steps: [5] },
    { durations: [10, 40, 50], steps: [5, 7, 20, 49.999, 50, 99, 100] },
    { durations: [10, 40, 50], steps: ['finish'] },
    { durations: [10, 40, 50], steps: [5, 'finish', 20, 'finish'] },
    { durations: [10, 40, 50], steps: [100] },
    { durations: [10, 40, 50], steps: [250, 3] },
    { durations: [30], steps: [0, 50, 'finish'] },
    { durations: [], steps: [10, 'finish'] },
    { durations: [0, 0, 5], steps: [1, 'finish'] },
    { durations: [1, 2, 3, 4], steps: [-5, 10, 9, 30.000001, 60, 'finish'] }
  ]
  for (const [i, script] of scripts.entries()) {
    await both('TrackProgressMonitor', `script #${i}`, 'server/objects/TrackProgressMonitor', (Monitor) => {
      const log = []
      const state = (m) => {
        const { trackStartedCallback, progressCallback, trackFinishedCallback, ...rest } = own(m)
        return { ...rest, callbacks: [typeof trackStartedCallback, typeof progressCallback, typeof trackFinishedCallback] }
      }
      const m = new Monitor(script.durations, (t) => log.push(['started', t]), (t, p, total) => log.push(['progress', t, p, total]), (t) => log.push(['finished', t]))
      log.push(['state', state(m)])
      for (const step of script.steps) {
        step === 'finish' ? m.finish() : m.update(step)
        log.push(['state', state(m)])
      }
      return log
    })
  }

  // ---------------------------------------------------------------- AudioTrack
  const fakeAudioFile = (overrides = {}) => {
    const metadata = { filename: 'track01.mp3', ext: '.mp3', clone() { return { ...this, cloned: true, toJSON() { return { filename: this.filename, ext: this.ext, cloned: true } } } } }
    return { index: 3, ino: '12345', duration: 123.45, mimeType: 'audio/mpeg', codec: 'mp3', metadata, ...overrides }
  }
  const metaNoName = { filename: '', clone() { return null } }
  await both('AudioTrack', 'fresh instance', 'server/objects/files/AudioTrack', (AudioTrack) => { const t = new AudioTrack(); return { own: own(t), json: t.toJSON() } })
  await both('AudioTrack', 'setFromStream', 'server/objects/files/AudioTrack', (AudioTrack) => { const t = new AudioTrack(); const r = t.setFromStream('Title', 3600.5, '/hls/abc/output.m3u8'); return { r, own: own(t), json: t.toJSON() } })
  await both('AudioTrack', 'setData', 'server/objects/files/AudioTrack', (AudioTrack) => { const t = new AudioTrack(); const r = t.setData('li_1', fakeAudioFile(), 42); return { r, keys: Object.keys(t), json: t.toJSON(), metaCloned: t.metadata.cloned } })
  await both('AudioTrack', 'setData without codec/filename, clone() returning null', 'server/objects/files/AudioTrack', (AudioTrack) => { const t = new AudioTrack(); t.setData('li_2', fakeAudioFile({ codec: undefined, metadata: metaNoName }), 0); return { own: own(t), json: t.toJSON() } })
  await both('AudioTrack', 'setData then setFromStream', 'server/objects/files/AudioTrack', (AudioTrack) => { const t = new AudioTrack(); t.setData('li_1', fakeAudioFile(), 42); t.setFromStream('S', 1, 'u'); return { keys: Object.keys(t), json: t.toJSON() } })
  await both('AudioTrack', 'setData with missing metadata', 'server/objects/files/AudioTrack', (AudioTrack) => { const t = new AudioTrack(); t.setData('li_1', { index: 1 }, 0); return own(t) })

  // ---------------------------------------------------------------- Task
  const title = { text: 'Encoding M4b', key: 'MessageTaskEncodingM4b' }
  const desc = { text: 'Encoding "X"', key: 'MessageTaskEncodingM4bDescription', subs: ['X'] }
  const failed = { text: 'Failed', key: 'MessageTaskFailed', subs: ['a', 'b'] }
  const taskSnapshot = (t) => ({ keys: Object.keys(t), own: maskId(own(t)), json: maskId(t.toJSON()), hasFailedAt: 'failedAt' in t })
  const taskScripts = {
    'fresh instance': (t) => {},
    'setData with data': (t) => t.setData('encode-m4b', title, desc, false, { libraryItemId: 'li_1', inos: ['1', '2'] }),
    'setData without data argument': (t) => t.setData('embed-metadata', title, desc, true),
    'setData with null data (PodcastManager opml-import)': (t) => t.setData('opml-import', title, desc, true, null),
    'setData with undefined data': (t) => t.setData('x', title, null, false, undefined),
    'setData with null description and keyless title': (t) => t.setData('library-scan', { text: 'Scanning' }, null, true, {}),
    'setData then setFailed': (t) => { t.setData('a', title, desc, false, {}); t.setFailed(failed) },
    'setFailed with keyless message': (t) => { t.setData('a', title, null, false); t.setFailed({ text: 'Oops' }) },
    'setData then setFinished()': (t) => { t.setData('a', title, desc, false, {}); t.setFinished() },
    'setFinished(new description)': (t) => { t.setData('a', title, desc, false, {}); t.setFinished({ text: 'Done', key: 'K', subs: ['1'] }) },
    'setFinished(keyless description)': (t) => { t.setData('a', title, desc, false, {}); t.setFinished({ text: 'Done' }) },
    'setFinished(null, true) clears description': (t) => { t.setData('a', title, desc, false, {}); t.setFinished(null, true) },
    'setFinished(null, false) keeps description': (t) => { t.setData('a', title, desc, false, {}); t.setFinished(null, false) },
    'data is copied, toJSON copies again': (t) => { const d = { n: 1 }; t.setData('a', title, null, false, d); d.n = 2; const j = t.toJSON(); j.data.n = 3; return { original: d, taskData: t.data } },
    'setData with no title throws': (t) => t.setData('a', undefined, null, false)
  }
  for (const [label, run] of Object.entries(taskScripts)) {
    await both('Task', label, 'server/objects/Task', (Task) => { resetClock(); const t = new Task(); const returned = run(t); return { returned, ...taskSnapshot(t) } })
  }
  await both('Task', 'ids are distinct uuids', 'server/objects/Task', (Task) => { const a = new Task(); const b = new Task(); a.setData('a', title, null, false); b.setData('a', title, null, false); return { distinct: a.id !== b.id, a: UUID_V4.test(a.id), b: UUID_V4.test(b.id) } })

  // ---------------------------------------------------------------- Notification
  const stored = { id: 'n1', libraryId: 'lib1', eventName: 'onBackupCompleted', urls: ['http://a', 'http://b'], titleTemplate: 'Backup {{backupCount}}', bodyTemplate: 'Path: {{backupPath}} Size: {{ backupSize }} Removed: {{removedOldest}} {{unknown}} {{backupPath}}', type: 'success', enabled: true, lastFiredAt: 5, lastAttemptFailed: true, numConsecutiveFailedAttempts: 2, numTimesFired: 9, createdAt: 1 }
  const sparse = { id: 'n2', eventName: 'onTest', createdAt: 2 }
  const eventData = { completionTime: 1700000000000, backupPath: 'path/to/$& backup $$ $1', backupSize: 12345, backupCount: 0, removedOldest: true, zero: 0, empty: '', nul: null }
  const notifSnapshot = (n) => ({ keys: Object.keys(n), own: maskId(own(n)), json: maskId(n.toJSON()) })
  const notifScripts = {
    'fresh instance': (N) => new N(),
    'new Notification(null)': (N) => new N(null),
    'construct from stored record': (N) => new N(stored),
    'construct from sparse (older) record': (N) => new N(sparse),
    'construct keeps the urls array by reference': (N) => { const n = new N(stored); return { __plain: n.urls === stored.urls } },
    'setData full payload': (N) => { const n = new N(); n.setData({ libraryId: 'lib', eventName: 'onTest', urls: ['u'], titleTemplate: 't', bodyTemplate: 'b', enabled: 1, type: 'info' }); return n },
    'setData minimal payload': (N) => { const n = new N(); n.setData({ eventName: 'onTest', urls: ['u'] }); return n },
    'update nothing': (N) => { const n = new N(stored); return { __plain: n.update({}), n: notifSnapshot(n) } },
    'update same values': (N) => { const n = new N(stored); return { __plain: n.update({ ...stored, urls: [...stored.urls] }), n: notifSnapshot(n) } },
    'update every key': (N) => { const n = new N(stored); const urls = ['x', 'y']; const r = n.update({ libraryId: null, eventName: 'onTest', urls, titleTemplate: 'T', bodyTemplate: 'B', enabled: false, type: null, id: 'ignored', numTimesFired: 99 }); return { __plain: r, copiedUrls: n.urls !== urls, n: notifSnapshot(n) } },
    'update re-enable resets failure state': (N) => { const n = new N({ ...stored, enabled: false }); const r = n.update({ enabled: true }); return { __plain: r, n: notifSnapshot(n) } },
    'update with enabled already true does not reset': (N) => { const n = new N(stored); const r = n.update({ enabled: true, type: 'warning' }); return { __plain: r, n: notifSnapshot(n) } },
    'update urls same content, different array': (N) => { const n = new N(stored); return { __plain: n.update({ urls: ['http://a', 'http://b'] }), same: n.urls === stored.urls } },
    'update with non-array urls throws': (N) => { const n = new N(stored); return { __plain: n.update({ urls: 'http://a' }) } },
    'updateNotificationFired sequence': (N) => { const n = new N(sparse); const steps = []; for (const ok of [false, false, true, false, 0, 'yes']) { n.updateNotificationFired(ok); steps.push(maskId(own(n))) } return { __plain: steps } },
    'templates': (N) => { const n = new N(stored); return { __plain: { title: n.parseTitleTemplate(eventData), body: n.parseBodyTemplate(eventData), payload: n.getApprisePayload(eventData), direct: n.replaceVariablesInTemplate('{{a}} {{ a }} {{a }} {{ a}} {{  a}} {{A}} {{a1}} {{}} {{a}}', { a: 'X', A: 7 }) } } },
    'templates with empty data': (N) => { const n = new N(stored); return { __plain: n.getApprisePayload({}) } },
    'templates with undefined data throw when a variable is present': (N) => { const n = new N(stored); return { __plain: n.getApprisePayload(undefined) } },
    'template with no variables and undefined data': (N) => { const n = new N({ ...sparse, titleTemplate: 'plain', bodyTemplate: 'text' }); return { __plain: n.getApprisePayload(undefined) } },
    'function value is used as a replacer': (N) => { const n = new N(sparse); return { __plain: n.replaceVariablesInTemplate('a {{x}} b', { x: (m) => `<${m}>` }) } }
  }
  for (const [label, run] of Object.entries(notifScripts)) {
    await both('Notification', label, 'server/objects/Notification', (N) => { resetClock(); const r = run(N); return r && '__plain' in r ? r : notifSnapshot(r) })
  }

  // ---------------------------------------------------------------- AudioMetaTags
  const probeTags = { file_tag_album: 'Album', file_tag_albumsort: 'Album, The', file_tag_artist: 'Artist', file_tag_track: '3/10', file_tag_disc: '1/2', file_tag_asin: 'B00TEST123', file_tag_overdrive_media_marker: '<Markers/>', file_tag_musicbrainz_trackid: 'mb-1', file_tag_isrc: 'ISRC', file_tag_creation_time: 'ignored', file_tag_genre: '' }
  const tagsSnapshot = (t) => ({ keys: Object.keys(t), own: own(t), json: t.toJSON(), jsonKeys: Object.keys(t.toJSON()), track: t.trackNumAndTotal, disc: t.discNumAndTotal, nums: [t.trackNumber, t.trackTotal, t.discNumber, t.discTotal] })
  const tagScripts = {
    'new AudioMetaTags()': (T) => tagsSnapshot(new T()),
    'new AudioMetaTags({})': (T) => tagsSnapshot(new T({})),
    'new AudioMetaTags(null)': (T) => tagsSnapshot(new T(null)),
    'construct from partial JSON': (T) => tagsSnapshot(new T({ tagTitle: 'T', tagASIN: 'A', tagTrack: '7', tagUnknown: 'ignored', tagGenre: '', tagDisc: null })),
    'setData from probe tags': (T) => { const t = new T(); const r = t.setData(probeTags); return { r, ...tagsSnapshot(t) } },
    'setData({}) clears': (T) => { const t = new T({ tagTitle: 'T' }); t.setData({}); return tagsSnapshot(t) },
    'setData(undefined) throws': (T) => { const t = new T(); return t.setData(undefined) },
    'updateData reports change then no change': (T) => { const t = new T(); return { first: t.updateData(probeTags), second: t.updateData(probeTags), third: t.updateData({ ...probeTags, file_tag_album: 'Other' }), fourth: t.updateData({}), ...tagsSnapshot(t) } },
    'clone is independent and equal': (T) => { const t = new T(); t.setData(probeTags); const c = t.clone(); const sameClass = c instanceof T; c.tagAlbum = 'Changed'; return { sameClass, original: t.tagAlbum, clone: tagsSnapshot(c), eqBefore: t.isEqual(t.clone()), eqAfter: t.isEqual(c) } },
