// Differential test: runs each converted module from two compiled trees (the pristine baseline build and a
// candidate build) on the same inputs and compares what they return, throw, and do to their collaborators.
//
// Usage: NODE_PATH=<repo>/node_modules node difftest.js <repo root> <baseline dist> <candidate dist> <temp dir>
const path = require('path')
const util = require('util')
const fs = require('fs')

const [repo, baseDist, candDist, tmpDir] = process.argv.slice(2)
const trees = { base: baseDist, cand: candDist }
const load = (tree, rel) => require(path.join(trees[tree], rel))

const show = (v) => util.inspect(v, { depth: null, breakLength: Infinity, maxArrayLength: null, maxStringLength: null })
const stats = {}
const failures = []
const throwMessages = new Set()

// Runs fn against both trees. Outcomes are compared as text produced by util.inspect, which is sensitive to
// values, types, undefined vs missing, and property ORDER.
async function both(moduleName, label, rel, fn) {
  const out = {}
  for (const tree of ['base', 'cand']) {
    try {
      out[tree] = { value: await fn(load(tree, rel), tree) }
    } catch (e) {
      const msg = e instanceof Error ? `${e.name}: ${e.message}` : `non-Error thrown: ${show(e)}`
      throwMessages.add(`${moduleName}: ${msg}`)
      out[tree] = { threw: msg }
    }
  }
  const s = (stats[moduleName] ||= { cases: 0, failed: 0 })
  s.cases++
  if (show(out.base) !== show(out.cand)) {
    s.failed++
    failures.push(`${moduleName} / ${label}\n    baseline : ${show(out.base).slice(0, 400)}\n    candidate: ${show(out.cand).slice(0, 400)}`)
  }
}

const own = (o) => Object.fromEntries(Object.entries(o)) // plain snapshot of own enumerable props, order preserved
const UUID_V4 = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/
const maskId = (o) => ({ ...o, id: UUID_V4.test(o.id) ? '<uuid v4>' : o.id })

async function main() {
  const realNow = Date.now
