    'searchTitle request fails': (ol) => ol.searchTitle('Nope'),
    'search': (ol) => ol.search({ q: 'x', limit: 2, flag: true }),
    'search request fails': (ol) => ol.search({ q: 'none' }),
    'search with no query': (ol) => ol.search({})
  }
  try {
    for (const [label, run] of Object.entries(openLibraryScripts)) {
      await both('OpenLibrary', label, 'server/providers/OpenLibrary', async (OpenLibrary) => {
        const calls = []
        const errors = []
        axios.get = (url, config) => {
          calls.push({ url, config })
          return url in responses ? Promise.resolve(responses[url]) : Promise.reject(new Error(`stubbed 404 for ${url}`))
        }
        console.error = (...args) => errors.push(args)
        const result = await run(new OpenLibrary())
        return { result, calls, errors }
      })
    }
  } finally {
    axios.get = realGet
    console.error = realConsoleError
  }

  Date.now = realNow

  // ---------------------------------------------------------------- report
  let total = 0
  let totalFailed = 0
  for (const [name, s] of Object.entries(stats)) {
    total += s.cases
    totalFailed += s.failed
    console.log(`${name.padEnd(26)} ${String(s.cases).padStart(5)} cases  ${s.failed ? `${s.failed} DIFFERENT` : 'all identical'}`)
  }
  console.log(`${'TOTAL'.padEnd(26)} ${String(total).padStart(5)} cases  ${totalFailed ? `${totalFailed} DIFFERENT` : 'all identical'}`)
  if (process.env.SHOW_THROWS) {
    console.log('\nDistinct exceptions observed (each was raised identically by both builds unless listed as a failure):')
    for (const m of [...throwMessages].sort()) console.log('  ' + m.slice(0, 200))
  }
  if (failures.length) {
    console.log(`\nFirst differences (${Math.min(failures.length, Number(process.env.MAX_FAILURES || 8))} of ${failures.length}):`)
    for (const f of failures.slice(0, Number(process.env.MAX_FAILURES || 8))) console.log('  ' + f)
  }
  process.exit(totalFailed ? 1 : 0)
}

main().catch((e) => {
  console.error('HARNESS ERROR', e)
  process.exit(2)
})

