// End-to-end smoke test against a running Audiobookshelf server. Prints a transcript made only of values that
// should be the same on every run (ids, tokens, timestamps and paths are masked), so that the transcript of one build
// can be compared with another's.
//
// Usage: node smoke.js <base url incl. router base path> <library folder> <transcript file>
const fs = require('fs')
const [base, libDir, outFile] = process.argv.slice(2)

const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'
const transcript = []
const record = (step, value) => {
  transcript.push({ step, value })
  console.log(`  ${step}: ${JSON.stringify(value)}`.slice(0, 600))
}
const sleep = (ms) => new Promise((r) => setTimeout(r, ms))
let token = null

async function call(method, path, body) {
  const headers = { 'User-Agent': UA }
  if (token) headers.Authorization = `Bearer ${token}`
  if (body !== undefined) headers['Content-Type'] = 'application/json'
  const res = await fetch(base + path, { method, headers, body: body === undefined ? undefined : JSON.stringify(body), redirect: 'manual' })
  const text = await res.text()
  let json = null
  try {
    json = JSON.parse(text)
  } catch {}
  return { status: res.status, json, text }
}

const pick = (o, keys) => Object.fromEntries(keys.map((k) => [k, o?.[k]]))
const isMs = (v) => typeof v === 'number' && v > 1600000000000
const maskNotification = (n) => ({ ...n, id: typeof n.id === 'string' && n.id.length === 36 ? '<uuid>' : n.id, createdAt: isMs(n.createdAt) ? '<ms>' : n.createdAt, lastFiredAt: isMs(n.lastFiredAt) ? '<ms>' : n.lastFiredAt })

async function main() {
  // ---- status / init / login
  let r = await call('GET', '/status')
  record('status before init', { http: r.status, ...pick(r.json, ['app', 'isInit', 'language']) })
  r = await call('POST', '/init', { newRoot: { username: 'root', password: 'smoke-pass' } })
  record('init', { http: r.status })
  r = await call('GET', '/status')
  record('status after init', { http: r.status, ...pick(r.json, ['app', 'isInit']), leaksPaths: 'ConfigPath' in (r.json || {}) })
  r = await call('POST', '/login', { username: 'root', password: 'smoke-pass' })
  token = r.json?.user?.accessToken || r.json?.user?.token
  record('login', { http: r.status, username: r.json?.user?.username, type: r.json?.user?.type, gotToken: !!token, source: r.json?.Source })
  if (!token) throw new Error('no token; login response keys: ' + Object.keys(r.json?.user || {}))

  // ---- parseUserAgent (GET /api/me/sessions)
  r = await call('GET', '/api/me/sessions')
  record('me/sessions deviceInfo', { http: r.status, total: r.json?.total, deviceInfo: (r.json?.sessions || []).map((s) => s.deviceInfo) })

  // ---- Notification (create / fire / update / delete)
  r = await call('GET', '/api/notifications')
  record('notifications initial', { http: r.status, events: r.json?.data?.events?.map((e) => e.name), settings: r.json?.settings })
  r = await call('PATCH', '/api/notifications', { appriseApiUrl: 'http://127.0.0.1:9/notify', maxFailedAttempts: 2, maxNotificationQueue: 5 })
  record('notification settings patch', { http: r.status })
  r = await call('POST', '/api/notifications', { libraryId: null, eventName: 'onTest', urls: ['json://127.0.0.1:9/a'], titleTemplate: 'Test on {{version}}', bodyTemplate: 'Body {{ version }} {{missing}}', enabled: true, type: 'info' })
  const notifId = r.json?.notifications?.[0]?.id
  record('notification created', { http: r.status, idIsUuid: /^[0-9a-f-]{36}$/.test(notifId || ''), notifications: r.json?.notifications?.map(maskNotification) })
  r = await call('POST', '/api/notifications', { eventName: '', urls: [] })
  record('notification rejected (no eventName)', { http: r.status, count: r.json?.notifications?.length })
  for (const attempt of [1, 2]) {
    r = await call('GET', '/api/notifications/test?fail=1')
    await sleep(1300) // notificationDelay is 1000 ms before the next event is accepted
    const s = await call('GET', '/api/notifications')
    record(`notification after failed attempt ${attempt}`, { http: r.status, notifications: s.json?.settings?.notifications?.map(maskNotification) })
  }
  r = await call('PATCH', `/api/notifications/${notifId}`, { id: notifId, titleTemplate: 'Changed {{version}}', urls: ['json://127.0.0.1:9/a', 'json://127.0.0.1:9/b'], enabled: true, type: 'warning' })
  record('notification updated (re-enabled)', { http: r.status, notifications: r.json?.notifications?.map(maskNotification) })
  r = await call('PATCH', `/api/notifications/${notifId}`, { id: notifId, titleTemplate: 'Changed {{version}}', type: 'warning' })
  record('notification update with same values', { http: r.status, notifications: r.json?.notifications?.map(maskNotification) })
  r = await call('DELETE', `/api/notifications/${notifId}`)
  record('notification deleted', { http: r.status, count: r.json?.notifications?.length })

  // ---- areEquivalent (EmailSettings.update)
  const email = { host: 'smtp.example.test', port: 2525, secure: false, user: 'u', pass: 'p', fromAddress: 'abs@example.test', ereaderDevices: [{ name: 'Kindle', email: 'k@example.test', availabilityOption: 'adminOrUp', users: [] }] }
  r = await call('PATCH', '/api/emails/settings', email)
  record('email settings patch', { http: r.status, settings: pick(r.json?.settings, ['host', 'port', 'secure', 'fromAddress', 'ereaderDevices']) })
  r = await call('PATCH', '/api/emails/settings', { ...email, ereaderDevices: [{ name: 'Kindle', email: 'k@example.test', availabilityOption: 'adminOrUp', users: [] }] })
  record('email settings patch (no change)', { http: r.status, settings: pick(r.json?.settings, ['host', 'port', 'ereaderDevices']) })

  // ---- library scan: globals, Task, parseNfoMetadata, parseFullName (author from folder), AudioMetaTags (ffprobe tags)
  r = await call('POST', '/api/libraries', { name: 'Smoke', folders: [{ fullPath: libDir }], mediaType: 'book' })
  const libraryId = r.json?.id
  record('library created', { http: r.status, name: r.json?.name, mediaType: r.json?.mediaType, folders: r.json?.folders?.length })
  r = await call('POST', `/api/libraries/${libraryId}/scan`)
  record('scan requested', { http: r.status })
  let tasksSeen = []
  let items = null
  for (let i = 0; i < 60; i++) {
    const t = await call('GET', '/api/tasks')
    for (const task of t.json?.tasks || []) tasksSeen.push(`${task.action}|${task.title}|finished=${task.isFinished}|failed=${task.isFailed}`)
    const li = await call('GET', `/api/libraries/${libraryId}/items?limit=10&minified=0`)
    if (li.json?.results?.length && !(t.json?.tasks || []).some((x) => x.action === 'library-scan')) {
      items = li
      break
    }
    await sleep(500)
  }
  record('scan tasks observed while polling (timing dependent, informational)', [...new Set(tasksSeen)])
  const item = items?.json?.results?.[0]
  record('library items after scan', {
    http: items?.status,
    total: items?.json?.total,
    items: (items?.json?.results || []).map((it) => ({ mediaType: it.mediaType, relPath: it.relPath, isFile: it.isFile, numFiles: it.numFiles, metadata: pick(it.media?.metadata, ['title', 'subtitle', 'authorName', 'narratorName', 'seriesName', 'genres', 'publishedYear', 'publisher', 'description', 'isbn', 'asin', 'language', 'abridged']), tags: it.media?.tags, numTracks: it.media?.numTracks, numAudioFiles: it.media?.numAudioFiles, duration: it.media?.duration }))
  })
  if (!item) throw new Error('scan produced no library item')
  r = await call('GET', `/api/items/${item.id}?expanded=1`)
  record('item audio files (AudioMetaTags via ffprobe)', {
    http: r.status,
    libraryFiles: (r.json?.libraryFiles || []).map((f) => ({ filename: f.metadata?.filename, fileType: f.fileType })).sort((a, b) => a.filename.localeCompare(b.filename)),
    audioFiles: (r.json?.media?.audioFiles || []).map((af) => ({ ...pick(af, ['index', 'trackNumFromMeta', 'discNumFromMeta', 'trackNumFromFilename', 'discNumFromFilename', 'format', 'duration', 'codec', 'channels', 'mimeType', 'metaTags']), filename: af.metadata?.filename })),
    authors: (r.json?.media?.metadata?.authors || []).map((a) => a.name),
    narrators: r.json?.media?.metadata?.narrators
  })
  // second listing goes through the count cache keyed by stringifySequelizeQuery()
  r = await call('GET', `/api/libraries/${libraryId}/items?limit=10&minified=0`)
  record('library items again (count cache)', { http: r.status, total: r.json?.total, titles: (r.json?.results || []).map((it) => it.media?.metadata?.title) })

  // ---- HLS session: hlsPlaylistGenerator + AudioTrack.setFromStream
  r = await call('POST', `/api/items/${item.id}/play`, { forceTranscode: true, mediaPlayer: 'smoke', supportedMimeTypes: [], deviceInfo: { clientName: 'smoke', clientVersion: '1' } })
  const sessionId = r.json?.id
  const mask = (s) => (typeof s === 'string' && sessionId ? s.split(sessionId).join('<session>') : s)
  record('play (forced transcode)', { http: r.status, playMethod: r.json?.playMethod, mediaPlayer: r.json?.mediaPlayer, duration: r.json?.duration, displayTitle: r.json?.displayTitle, displayAuthor: r.json?.displayAuthor, audioTracks: (r.json?.audioTracks || []).map((t) => ({ ...t, contentUrl: mask(t.contentUrl) })) })
  if (sessionId) {
    const pl = await call('GET', `/hls/${sessionId}/output.m3u8?token=${token}`)
    record('hls playlist', { http: pl.status, playlist: pl.text })
    r = await call('POST', `/api/session/${sessionId}/close`, {})
    record('session closed', { http: r.status })
  }

  // ---- LongTimeout (share that expires in the future, then removed)
  r = await call('POST', '/api/share/mediaitem', { slug: 'smoke-share', mediaItemType: 'book', mediaItemId: item.media?.id, expiresAt: Date.now() + 3600 * 1000 * 24 * 40, isDownloadable: false })
  const shareId = r.json?.id
  record('share created (40 days: longer than a 32-bit timeout)', { http: r.status, slug: r.json?.slug, mediaItemType: r.json?.mediaItemType, hasExpiry: !!r.json?.expiresAt })
  if (shareId) {
    r = await call('DELETE', `/api/share/mediaitem/${shareId}`)
    record('share deleted', { http: r.status })
  }

  r = await call('GET', '/ping')
  record('ping at end', { http: r.status, body: r.json })
}

main()
  .then(() => {
    fs.writeFileSync(outFile, JSON.stringify(transcript, null, 1))
    console.log('SMOKE DONE')
  })
  .catch((e) => {
    fs.writeFileSync(outFile, JSON.stringify(transcript, null, 1))
    console.log('SMOKE FAILED:', e.message)
    process.exit(1)
  })

