SP="/c/Users/USER/AppData/Local/Temp/claude/D--SEM-2-574-po-s06-run-audiobookshelf/44babef5-5841-4659-9823-eee1f53febf0/scratchpad" && for l in baseline new-clean new-real; do echo "=== $l: lines matching ERROR/FATAL ==="; grep -i -E "\b(ERROR|FATAL)\b" "$SP/e2e/$l/server.log" | sed -E 's/onTest\/[0-9a-f-]{36}/onTest\/<uuid>/; s/^\[[^]]*\] //' | cut -c1-120; done; echo; echo "=== transcript comparison ==="; cd "$SP" && node -e "
const fs=require('fs');
const load=(l)=>JSON.parse(fs.readFileSync('e2e/'+l+'/transcript.json','utf8'));
const b=load('baseline'), n=load('new-clean'), r=load('new-real');
const informational=(s)=>s.step.includes('informational');
const cmp=(x,y,name)=>{
  let same=0, diff=[];
  const max=Math.max(x.length,y.length);
  for(let i=0;i<max;i++){
    const a=x[i], c=y[i];
    if(a && c && a.step===c.step && informational(a)) { continue }
    if(a && c && a.step===c.step && JSON.stringify(a.value)===JSON.stringify(c.value)) same++; else diff.push((a&&a.step)||(c&&c.step));
  }
  console.log(name+': '+same+' steps identical, '+diff.length+' differ'+(diff.length?' -> '+JSON.stringify(diff):''));
};
console.log('steps recorded: baseline='+b.length+' new-clean='+n.length+' new-real='+r.length);
cmp(b,n,'baseline  vs new build (same layout)');
cmp(b,r,'baseline  vs new build (repo layout, as npm start runs it)');
for(const l of [['baseline',b],['new-clean',n],['new-real',r]]) console.log(l[0]+' scan task lines (informational): '+JSON.stringify(l[1].find(informational).value));
"

