const describe = (v) => (v === null ? 'null (request failed)' : typeof v === 'string' ? `string, ${v.length} chars, starts ${JSON.stringify(v.slice(0, 30))}` : typeof v)
const firstDiff = (a, b) => { let i = 0; while (i < a.length && i < b.length && a[i] === b[i]) i++; return i }
