;(async () => {
  const base = load(baseDist)
  const cand = load(candDist)
  const b1 = await base.get('/isbn/9780756404741', 45000); await sleep(1500)
  const c1 = await cand.get('/isbn/9780756404741', 45000); await sleep(1500)
  const b2 = await base.get('/isbn/9780756404741', 45000)
  console.log('baseline, request 1 :', describe(b1))
  console.log('new build, request  :', describe(c1))
  console.log('baseline, request 2 :', describe(b2))
  const eq = (x, y) => JSON.stringify(x) === JSON.stringify(y)
  console.log('baseline request 1 == baseline request 2 :', eq(b1, b2), '  <- same code both times')
  console.log('baseline request 1 == new build          :', eq(b1, c1))
  for (const [name, x, y] of [['baseline1 vs baseline2', b1, b2], ['baseline1 vs new', b1, c1]]) {
    if (typeof x === 'string' && typeof y === 'string' && x !== y) { const p = firstDiff(x, y); console.log(`  ${name}: first difference at char ${p}: ${JSON.stringify(x.slice(p - 50, p + 50))}  vs  ${JSON.stringify(y.slice(p - 50, p + 50))}`) }
  }
})().catch((e) => { console.log('LIVE CHECK ERROR', e.message); process.exit(1) })
EOF
