  res.writeHead(404, { 'Content-Type': 'text/plain' }); res.end('not found')
})

async function run(dist, port) {
  const OpenLibrary = require(path.join(dist, 'server/providers/OpenLibrary'))
  const ol = new OpenLibrary()
  ol.baseUrl = `http://127.0.0.1:${port}`
  const errors = []
  const realError = console.error
  console.error = (...a) => errors.push(a.join(' ').replace(/:\d{4,5}\b/g, ':<port>'))
  log = []
  const out = {}
  try {
    out.searchTitle = await ol.searchTitle('Good Book', 3000)
    out.isbnHtml = await ol.isbnLookup('111')
    out.isbnJson = await ol.isbnLookup('333')
    out.isbnMissing = await ol.isbnLookup('999')
    out.timedOut = await ol.get('slow', 300)
    out.slowButInTime = await ol.get('slow', 3000)
  } finally { console.error = realError }
  const dynamic = [await ol.isbnLookup('222'), await ol.isbnLookup('222')]
  return { out, errors, requests: log.filter((l) => !l.includes('/isbn/222')), dynamic }
}

server.listen(0, '127.0.0.1', async () => {
  const port = server.address().port
  try {
    const base = await run(baseDist, port)
    const cand = await run(candDist, port)
    const same = (k) => JSON.stringify(base[k]) === JSON.stringify(cand[k])
    console.log('search hits (new build):', JSON.stringify(cand.out.searchTitle).slice(0, 700))
    console.log('isbn -> HTML page      :', JSON.stringify(cand.out.isbnHtml), `(typeof ${typeof cand.out.isbnHtml})`)
    console.log('isbn -> JSON           :', JSON.stringify(cand.out.isbnJson))
    console.log('isbn -> 404            :', JSON.stringify(cand.out.isbnMissing))
    console.log('get() past its timeout :', JSON.stringify(cand.out.timedOut), '| within timeout:', JSON.stringify(cand.out.slowButInTime))
    console.log('HTTP requests issued   :', JSON.stringify(cand.requests))
    console.log('errors logged          :', JSON.stringify(cand.errors))
    console.log('---')
    console.log('results identical between baseline and new build        :', same('out'))
    console.log('HTTP requests identical between baseline and new build  :', same('requests'))
    console.log('logged errors identical between baseline and new build  :', same('errors'))
    console.log('dynamic HTML page: same build, two requests, identical? :', base.dynamic[0] === base.dynamic[1], ' <- a page that changes per request differs even with unchanged code')
  } catch (e) { console.log('LOCAL HTTP CHECK ERROR', e) } finally { server.close() }
})
EOF
