import axiosModule = require('axios')
const axios = axiosModule.default

// lib.d.ts types isNaN(number), but the built-in coerces every value and parsePublishYear() calls it with the year part of a date string. Widens the type for this file only; emits no code.
declare function isNaN(value: unknown): boolean

// The three interfaces below describe OpenLibrary's JSON, limited to the fields that are read here. It is external data: the server does not validate it.

/** A doc in a search.json response */
interface OpenLibrarySearchDoc {
  key: string
  title: string
  author_name?: string[]
  first_publish_year?: number
  cover_edition_key?: string
}

interface OpenLibrarySearchResponse {
  docs: OpenLibrarySearchDoc[]
}

/** A works record (<works key>.json) */
interface OpenLibraryWorksResponse {
  covers?: number[]
  description?: string | { value?: string }
  first_publish_date?: string
}

/** Returned in place of data when a request to OpenLibrary fails */
interface OpenLibraryRequestError {
  errorCode: 404
}

/** Returned by getWorksData() when the works request fails. cleanSearchDoc() spreads it into the search hit just like a successful result. */
interface OpenLibraryWorksError {
  errorMsg: string
  errorCode: 500
  first_publish_date?: undefined // read by parsePublishYear() without checking for the error first
}

interface OpenLibraryWorksData {
  /** Last segment of the works key. split() never returns an empty array, hence the non-null assertion in getWorksData(). */
  id: string
  key: string
  covers: string[]
  first_publish_date: string | undefined
  description: string | null
}

/** A search hit: fields from the search doc, with the works data (or the works error) spread over them */
type OpenLibrarySearchResult = {
  title: string
  author: string | null
  publishedYear: string | null
  edition: string | undefined
  cover: string | null
} & (OpenLibraryWorksData | OpenLibraryWorksError)

class OpenLibrary {
  #responseTimeout = 10000

  declare baseUrl: string

  constructor() {
    this.baseUrl = 'https://openlibrary.org'
  }

  /**
   *
   * @template T the shape the caller expects back; the response is not checked against it
   * @param {string} uri
   * @param {number} timeout
   * @returns {Promise<Object>}
   */
  get<T>(uri: string, timeout: number = this.#responseTimeout): Promise<T | null> {
    if (!timeout || isNaN(timeout)) timeout = this.#responseTimeout
    return axios
      .get<T>(`${this.baseUrl}/${uri}`, {
        timeout
      })
      .then((res) => {
        return res.data
      })
      .catch((error) => {
        console.error('Failed', error.message)
        return null
      })
  }

  /**
   * The URL has no ".json" suffix, and OpenLibrary answers it with the book's HTML page, so in practice this resolves to that page as a string rather than to a JSON record.
   * Left as it was, since changing the URL would change behaviour. Its only caller is BookFinder.findByISBN(), which nothing calls at the time of writing.
   */
  async isbnLookup(isbn: string): Promise<Record<string, unknown> | string | OpenLibraryRequestError> {
    var lookupData = await this.get<Record<string, unknown> | string>(`/isbn/${isbn}`)
    if (!lookupData) {
      return {
        errorCode: 404
      }
    }
    return lookupData
  }

  async getWorksData(worksKey: string): Promise<OpenLibraryWorksData | OpenLibraryWorksError> {
    var worksData = await this.get<OpenLibraryWorksResponse>(`${worksKey}.json`)
    if (!worksData) {
      return {
        errorMsg: 'Works Data Request failed',
        errorCode: 500
      }
    }
    if (!worksData.covers) worksData.covers = []
    var coverImages = worksData.covers.filter((c) => c > 0).map((c) => `https://covers.openlibrary.org/b/id/${c}-L.jpg`)
    var description: string | null = null
    if (worksData.description) {
      if (typeof worksData.description === 'string') {
        description = worksData.description
      } else {
        description = worksData.description.value || null
      }
    }
    return {
      id: worksKey.split('/').pop()!,
      key: worksKey,
      covers: coverImages,
      first_publish_date: worksData.first_publish_date,
      description: description
    }
  }

  parsePublishYear(doc: OpenLibrarySearchDoc, worksData: OpenLibraryWorksData | OpenLibraryWorksError): string | null {
    if (doc.first_publish_year && !isNaN(doc.first_publish_year)) return String(doc.first_publish_year)
    if (worksData.first_publish_date) {
      var year = worksData.first_publish_date.split('-')[0]
      if (!isNaN(year)) return String(year)
    }
    return null
  }

  async cleanSearchDoc(doc: OpenLibrarySearchDoc): Promise<OpenLibrarySearchResult> {
    var worksData = await this.getWorksData(doc.key)
    return {
      title: doc.title,
      author: doc.author_name ? doc.author_name.join(', ') : null,
      publishedYear: this.parsePublishYear(doc, worksData),
      edition: doc.cover_edition_key,
      cover: doc.cover_edition_key ? `https://covers.openlibrary.org/b/OLID/${doc.cover_edition_key}-L.jpg` : null,
      ...worksData
    }
  }

  async search(query: Record<string, string | number | boolean>): Promise<OpenLibrarySearchResult[] | OpenLibraryRequestError> {
    var queryString = Object.keys(query)
      .map((key) => key + '=' + query[key])
      .join('&')
    var lookupData = await this.get<OpenLibrarySearchResponse>(`/search.json?${queryString}`)
    if (!lookupData) {
      return {
        errorCode: 404
      }
    }
    var searchDocs = await Promise.all(lookupData.docs.map((d) => this.cleanSearchDoc(d)))
    return searchDocs
  }

  /**
   *
   * @param {string} title
   * @param {number} timeout
   * @returns {Promise<Object[]>}
   */
  async searchTitle(title: string, timeout: number = this.#responseTimeout): Promise<OpenLibrarySearchResult[] | OpenLibraryRequestError> {
    title = encodeURIComponent(title)
    var lookupData = await this.get<OpenLibrarySearchResponse>(`/search.json?title=${title}`, timeout)
    if (!lookupData) {
      return {
        errorCode: 404
      }
    }
    var searchDocs = await Promise.all(lookupData.docs.map((d) => this.cleanSearchDoc(d)))
    return searchDocs
  }
}
export = OpenLibrary

// End-to-end smoke test against a running Audiobookshelf server. Prints a transcript made only of values that
// should be the same on every run (ids, tokens, timestamps and paths are masked), so that the transcript of one build
// can be compared with another's.
//
// Usage: node smoke.js <base url incl. router base path> <library folder> <transcript file>
const fs = require('fs')
const [base, libDir, outFile] = process.argv.slice(2)

const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'
const transcript = []
const record = (step, value) => {
  transcript.push({ step, value })
  console.log(`  ${step}: ${JSON.stringify(value)}`.slice(0, 600))
}
const sleep = (ms) => new Promise((r) => setTimeout(r, ms))
let token = null

async function call(method, path, body) {
  const headers = { 'User-Agent': UA }
  if (token) headers.Authorization = `Bearer ${token}`
  if (body !== undefined) headers['Content-Type'] = 'application/json'
  const res = await fetch(base + path, { method, headers, body: body === undefined ? undefined : JSON.stringify(body), redirect: 'manual' })
  const text = await res.text()
  let json = null
  try {
    json = JSON.parse(text)
  } catch {}
  return { status: res.status, json, text }
}

const pick = (o, keys) => Object.fromEntries(keys.map((k) => [k, o?.[k]]))
const isMs = (v) => typeof v === 'number' && v > 1600000000000
const maskNotification = (n) => ({ ...n, id: typeof n.id === 'string' && n.id.length === 36 ? '<uuid>' : n.id, createdAt: isMs(n.createdAt) ? '<ms>' : n.createdAt, lastFiredAt: isMs(n.lastFiredAt) ? '<ms>' : n.lastFiredAt })

async function main() {
  // ---- status / init / login
  let r = await call('GET', '/status')
  record('status before init', { http: r.status, ...pick(r.json, ['app', 'isInit', 'language']) })
  r = await call('POST', '/init', { newRoot: { username: 'root', password: 'smoke-pass' } })
  record('init', { http: r.status })
  r = await call('GET', '/status')
  record('status after init', { http: r.status, ...pick(r.json, ['app', 'isInit']), leaksPaths: 'ConfigPath' in (r.json || {}) })
  r = await call('POST', '/login', { username: 'root', password: 'smoke-pass' })
  token = r.json?.user?.accessToken || r.json?.user?.token
  record('login', { http: r.status, username: r.json?.user?.username, type: r.json?.user?.type, gotToken: !!token, source: r.json?.Source })
  if (!token) throw new Error('no token; login response keys: ' + Object.keys(r.json?.user || {}))

  // ---- parseUserAgent (GET /api/me/sessions)
  r = await call('GET', '/api/me/sessions')
  record('me/sessions deviceInfo', { http: r.status, total: r.json?.total, deviceInfo: (r.json?.sessions || []).map((s) => s.deviceInfo) })

  // ---- Notification (create / fire / update / delete)
  r = await call('GET', '/api/notifications')
  record('notifications initial', { http: r.status, events: r.json?.data?.events?.map((e) => e.name), settings: r.json?.settings })
  r = await call('PATCH', '/api/notifications', { appriseApiUrl: 'http://127.0.0.1:9/notify', maxFailedAttempts: 2, maxNotificationQueue: 5 })
  record('notification settings patch', { http: r.status })
  r = await call('POST', '/api/notifications', { libraryId: null, eventName: 'onTest', urls: ['json://127.0.0.1:9/a'], titleTemplate: 'Test on {{version}}', bodyTemplate: 'Body {{ version }} {{missing}}', enabled: true, type: 'info' })
  const notifId = r.json?.notifications?.[0]?.id
  record('notification created', { http: r.status, idIsUuid: /^[0-9a-f-]{36}$/.test(notifId || ''), notifications: r.json?.notifications?.map(maskNotification) })
  r = await call('POST', '/api/notifications', { eventName: '', urls: [] })
  record('notification rejected (no eventName)', { http: r.status, count: r.json?.notifications?.length })
  for (const attempt of [1, 2]) {
    r = await call('GET', '/api/notifications/test?fail=1')
    await sleep(1300) // notificationDelay is 1000 ms before the next event is accepted
    const s = await call('GET', '/api/notifications')
    record(`notification after failed attempt ${attempt}`, { http: r.status, notifications: s.json?.settings?.notifications?.map(maskNotification) })
  }
  r = await call('PATCH', `/api/notifications/${notifId}`, { id: notifId, titleTemplate: 'Changed {{version}}', urls: ['json://127.0.0.1:9/a', 'json://127.0.0.1:9/b'], enabled: true, type: 'warning' })
  record('notification updated (re-enabled)', { http: r.status, notifications: r.json?.notifications?.map(maskNotification) })
  r = await call('PATCH', `/api/notifications/${notifId}`, { id: notifId, titleTemplate: 'Changed {{version}}', type: 'warning' })
  record('notification update with same values', { http: r.status, notifications: r.json?.notifications?.map(maskNotification) })
  r = await call('DELETE', `/api/notifications/${notifId}`)
  record('notification deleted', { http: r.status, count: r.json?.notifications?.length })

  // ---- areEquivalent (EmailSettings.update)
  const email = { host: 'smtp.example.test', port: 2525, secure: false, user: 'u', pass: 'p', fromAddress: 'abs@example.test', ereaderDevices: [{ name: 'Kindle', email: 'k@example.test', availabilityOption: 'adminOrUp', users: [] }] }
  r = await call('PATCH', '/api/emails/settings', email)
  record('email settings patch', { http: r.status, settings: pick(r.json?.settings, ['host', 'port', 'secure', 'fromAddress', 'ereaderDevices']) })
  r = await call('PATCH', '/api/emails/settings', { ...email, ereaderDevices: [{ name: 'Kindle', email: 'k@example.test', availabilityOption: 'adminOrUp', users: [] }] })
  record('email settings patch (no change)', { http: r.status, settings: pick(r.json?.settings, ['host', 'port', 'ereaderDevices']) })

  // ---- library scan: globals, Task, parseNfoMetadata, parseFullName (author from folder), AudioMetaTags (ffprobe tags)
  r = await call('POST', '/api/libraries', { name: 'Smoke', folders: [{ fullPath: libDir }], mediaType: 'book' })
  const libraryId = r.json?.id
  record('library created', { http: r.status, name: r.json?.name, mediaType: r.json?.mediaType, folders: r.json?.folders?.length })
  r = await call('POST', `/api/libraries/${libraryId}/scan`)
  record('scan requested', { http: r.status })
  let tasksSeen = []
  let items = null
  for (let i = 0; i < 60; i++) {
    const t = await call('GET', '/api/tasks')
    for (const task of t.json?.tasks || []) tasksSeen.push(`${task.action}|${task.title}|finished=${task.isFinished}|failed=${task.isFailed}`)
    const li = await call('GET', `/api/libraries/${libraryId}/items?limit=10&minified=0`)
    if (li.json?.results?.length && !(t.json?.tasks || []).some((x) => x.action === 'library-scan')) {
      items = li
      break
    }
    await sleep(500)
  }
  record('scan tasks observed while polling (timing dependent, informational)', [...new Set(tasksSeen)])
  const item = items?.json?.results?.[0]
  record('library items after scan', {
    http: items?.status,
    total: items?.json?.total,
    items: (items?.json?.results || []).map((it) => ({ mediaType: it.mediaType, relPath: it.relPath, isFile: it.isFile, numFiles: it.numFiles, metadata: pick(it.media?.metadata, ['title', 'subtitle', 'authorName', 'narratorName', 'seriesName', 'genres', 'publishedYear', 'publisher', 'description', 'isbn', 'asin', 'language', 'abridged']), tags: it.media?.tags, numTracks: it.media?.numTracks, numAudioFiles: it.media?.numAudioFiles, duration: it.media?.duration }))
  })
  if (!item) throw new Error('scan produced no library item')
  r = await call('GET', `/api/items/${item.id}?expanded=1`)
  record('item audio files (AudioMetaTags via ffprobe)', {
    http: r.status,
    libraryFiles: (r.json?.libraryFiles || []).map((f) => ({ filename: f.metadata?.filename, fileType: f.fileType })).sort((a, b) => a.filename.localeCompare(b.filename)),
    audioFiles: (r.json?.media?.audioFiles || []).map((af) => ({ ...pick(af, ['index', 'trackNumFromMeta', 'discNumFromMeta', 'trackNumFromFilename', 'discNumFromFilename', 'format', 'duration', 'codec', 'channels', 'mimeType', 'metaTags']), filename: af.metadata?.filename })),
    authors: (r.json?.media?.metadata?.authors || []).map((a) => a.name),
    narrators: r.json?.media?.metadata?.narrators
  })
  // second listing goes through the count cache keyed by stringifySequelizeQuery()
  r = await call('GET', `/api/libraries/${libraryId}/items?limit=10&minified=0`)
  record('library items again (count cache)', { http: r.status, total: r.json?.total, titles: (r.json?.results || []).map((it) => it.media?.metadata?.title) })

  // ---- HLS session: hlsPlaylistGenerator + AudioTrack.setFromStream
  r = await call('POST', `/api/items/${item.id}/play`, { forceTranscode: true, mediaPlayer: 'smoke', supportedMimeTypes: [], deviceInfo: { clientName: 'smoke', clientVersion: '1' } })
  const sessionId = r.json?.id
  const mask = (s) => (typeof s === 'string' && sessionId ? s.split(sessionId).join('<session>') : s)
  record('play (forced transcode)', { http: r.status, playMethod: r.json?.playMethod, mediaPlayer: r.json?.mediaPlayer, duration: r.json?.duration, displayTitle: r.json?.displayTitle, displayAuthor: r.json?.displayAuthor, audioTracks: (r.json?.audioTracks || []).map((t) => ({ ...t, contentUrl: mask(t.contentUrl) })) })
  if (sessionId) {
    const pl = await call('GET', `/hls/${sessionId}/output.m3u8?token=${token}`)
    record('hls playlist', { http: pl.status, playlist: pl.text })
    r = await call('POST', `/api/session/${sessionId}/close`, {})
    record('session closed', { http: r.status })
  }

  // ---- LongTimeout (share that expires in the future, then removed)
  r = await call('POST', '/api/share/mediaitem', { slug: 'smoke-share', mediaItemType: 'book', mediaItemId: item.media?.id, expiresAt: Date.now() + 3600 * 1000 * 24 * 40, isDownloadable: false })
  const shareId = r.json?.id
  record('share created (40 days: longer than a 32-bit timeout)', { http: r.status, slug: r.json?.slug, mediaItemType: r.json?.mediaItemType, hasExpiry: !!r.json?.expiresAt })
  if (shareId) {
    r = await call('DELETE', `/api/share/mediaitem/${shareId}`)
    record('share deleted', { http: r.status })
  }

  r = await call('GET', '/ping')
  record('ping at end', { http: r.status, body: r.json })
}

main()
  .then(() => {
    fs.writeFileSync(outFile, JSON.stringify(transcript, null, 1))
    console.log('SMOKE DONE')
  })
  .catch((e) => {
    fs.writeFileSync(outFile, JSON.stringify(transcript, null, 1))
    console.log('SMOKE FAILED:', e.message)
    process.exit(1)
  })

// Compares the compiled output of converted modules against the pristine baseline build at the syntax-tree level.
// Two files are AST-identical when they are the same program: they may differ only in comments, whitespace,
// quote style and redundant parentheses, none of which can change behaviour.
//
// Usage: node astdiff.js <repo root> <baseline dist dir> <relative path without extension> [...]
const fs = require('fs')
const path = require('path')

const [repoRoot, baselineDir, ...rels] = process.argv.slice(2)
const acorn = require(path.join(repoRoot, 'node_modules', 'acorn'))

function parse(file) {
  const src = fs.readFileSync(file, 'utf8')
  const comments = []
  const ast = acorn.parse(src, { ecmaVersion: 'latest', sourceType: 'script', allowHashBang: true, onComment: comments })
  return { ast, src, comments }
}

// Drop position info. Literal.raw is dropped too (quote style / numeric spelling), but the cooked `value`,
// `regex` and `bigint` fields are kept, and TemplateElement.value.raw is kept.
function clean(node, parentType) {
  if (Array.isArray(node)) return node.map((n) => clean(n, parentType))
  if (node && typeof node === 'object') {
    if (node instanceof RegExp) return { __regexp: String(node) }
    const out = {}
    for (const key of Object.keys(node)) {
      if (key === 'start' || key === 'end' || key === 'loc' || key === 'range') continue
      if (key === 'raw' && node.type === 'Literal') continue
      const v = node[key]
      out[key] = typeof v === 'bigint' ? { __bigint: String(v) } : clean(v, node.type)
    }
    return out
  }
  return node
}

function firstDifference(a, b, trail) {
  if (a === b) return null
  if (typeof a !== typeof b || a === null || b === null || typeof a !== 'object') return `${trail}: ${JSON.stringify(a)} !== ${JSON.stringify(b)}`
  if (Array.isArray(a) !== Array.isArray(b)) return `${trail}: array/object mismatch`
  const keys = new Set([...Object.keys(a), ...Object.keys(b)])
  for (const key of keys) {
    if (!(key in a) || !(key in b)) return `${trail}.${key}: present on one side only`
    const d = firstDifference(a[key], b[key], `${trail}.${key}`)
    if (d) return d
  }
  return null
}

// JavaScript instantiates every top-level function declaration before the first statement of the file runs, so where a
// function declaration sits relative to the other statements cannot affect execution. Model that by moving them to the
// front, keeping the relative order of the declarations and of the remaining statements (tsc emits `export =` last).
function hoistFunctionDeclarations(program) {
  const fns = program.body.filter((n) => n.type === 'FunctionDeclaration')
  const rest = program.body.filter((n) => n.type !== 'FunctionDeclaration')
  return { ...program, body: [...fns, ...rest] }
}

function countIdentifier(node, name) {
  if (Array.isArray(node)) return node.reduce((n, child) => n + countIdentifier(child, name), 0)
  if (node && typeof node === 'object') {
    let n = node.type === 'Identifier' && node.name === name ? 1 : 0
    for (const key of Object.keys(node)) n += countIdentifier(node[key], name)
    return n
  }
  return 0
}

// `import X = require('m')` followed by `const Y = X.member` compiles to two statements where the JavaScript source had
// `const Y = require('m').member`. When X is a top-level const, the very next statement is its only use, and that use is a
// plain member read, folding the two back together cannot change evaluation order or anything observable.
// Any other occurrence of the name X anywhere in the file (even as a property name) disables the rewrite.
function inlineSingleUseRequire(program) {
  const body = []
  for (let i = 0; i < program.body.length; i++) {
    const a = program.body[i]
    const b = program.body[i + 1]
    const isRequireConst = a.type === 'VariableDeclaration' && a.kind === 'const' && a.declarations.length === 1 && a.declarations[0].id.type === 'Identifier' && a.declarations[0].init?.type === 'CallExpression' && a.declarations[0].init.callee.type === 'Identifier' && a.declarations[0].init.callee.name === 'require'
    if (isRequireConst && b && b.type === 'VariableDeclaration' && b.kind === 'const' && b.declarations.length === 1) {
      const name = a.declarations[0].id.name
      const init = b.declarations[0].init
      if (init?.type === 'MemberExpression' && !init.computed && !init.optional && init.object.type === 'Identifier' && init.object.name === name && countIdentifier(program, name) === 2) {
        body.push({ ...b, declarations: [{ ...b.declarations[0], init: { ...init, object: a.declarations[0].init } }] })
        i++
        continue
      }
    }
    body.push(a)
  }
  return { ...program, body }
}

let failed = false
for (const rel of rels) {
  const baseFile = path.join(baselineDir, rel + '.js')
  const newFile = path.join(repoRoot, 'dist-server', rel + '.js')
  const base = parse(baseFile)
  const now = parse(newFile)
  const baseAst = clean(base.ast)
  const nowAst = clean(now.ast)
  const diff = firstDifference(baseAst, nowAst, 'Program')
  const bytes = base.src === now.src
  const commentsSame = JSON.stringify(base.comments.map((c) => c.value)) === JSON.stringify(now.comments.map((c) => c.value))
  let verdict
  if (bytes) verdict = 'BYTE-IDENTICAL'
  else if (!diff) verdict = `AST-IDENTICAL (text differs${commentsSame ? '' : '; comments differ'})`
  else {
    const hoistedDiff = firstDifference(hoistFunctionDeclarations(baseAst), hoistFunctionDeclarations(nowAst), 'Program')
    const inlinedDiff = firstDifference(inlineSingleUseRequire(baseAst), inlineSingleUseRequire(nowAst), 'Program')
    if (!hoistedDiff) verdict = `AST-IDENTICAL AFTER HOISTING (only the position of a statement relative to hoisted top-level function declarations differs${commentsSame ? '' : '; comments differ'})`
    else if (!inlinedDiff) verdict = `AST-IDENTICAL AFTER INLINING (only difference: a require() result is bound to a const that is read once, on the next line${commentsSame ? '' : '; comments differ'})`
    else {
      verdict = `DIFFERENT -> ${diff}`
      failed = true
    }
  }
  console.log(`${rel}.js: ${verdict}`)
}
process.exit(failed ? 1 : 0)
